  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: The Prophet of Salvation: Isaiah$j$, $j${"questions": [{"q": "What was the main work of an Old Testament prophet?", "options": ["Speaking God's message and calling the people back to the covenant", "Keeping the temple records", "Building cities", "Leading armies"]}, {"q": "What did Isaiah say when God asked whom He should send?", "options": ["Let someone else go", "Send my brother", "Here am I; send me", "I am not able"]}, {"q": "What does Isaiah 9:6 promise?", "options": ["A child who would be born and a son who would be given", "A famine", "A flood", "A new temple of gold"]}, {"q": "How does Isaiah 40 begin?", "options": ["With the words, Comfort ye my people", "With a warning of war", "With a list of kings", "With a curse"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Prophet of Salvation: Isaiah$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,0}'::int[], array[$j$A prophet was a messenger who spoke for God.$j$,$j$Isaiah answered, Here am I; send me (Isaiah 6:8).$j$,$j$Isaiah 9:6 speaks of a child born and a son given, whose name is Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.$j$,$j$Isaiah 40 begins with a message of comfort.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Prophet of Salvation: Isaiah$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: The Weeping Prophet: Jeremiah and Lamentations$j$, $j${"questions": [{"q": "Why is Jeremiah often called the weeping prophet?", "options": ["He sang sad songs", "He was a poor man", "He lived in a cave", "He grieved over the sin and coming fall of his people"]}, {"q": "Which nation destroyed Jerusalem in Jeremiah's time?", "options": ["Egypt", "Rome", "Assyria", "Babylon"]}, {"q": "What does Lamentations 3:22 and 23 say about the LORD's mercies?", "options": ["They have an end", "They are only for kings", "They fail in the evening", "They are new every morning"]}, {"q": "What did God promise to do in the new covenant of Jeremiah 31?", "options": ["End all prophecy", "Remove the temple", "Send them back to Egypt", "Write His law in their hearts"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Weeping Prophet: Jeremiah and Lamentations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,3,3}'::int[], array[$j$Jeremiah mourned for Judah as he warned of the coming judgment.$j$,$j$Babylon took Jerusalem and carried Judah into exile.$j$,$j$His compassions fail not; they are new every morning.$j$,$j$God promised to put His law in their inward parts and write it in their hearts.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Weeping Prophet: Jeremiah and Lamentations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Visions of Glory: Ezekiel$j$, $j${"questions": [{"q": "Where was Ezekiel when God called him?", "options": ["On Mount Sinai", "In the temple at Jerusalem", "In Egypt", "By the river Chebar in Babylon"]}, {"q": "What is a watchman's job in Ezekiel?", "options": ["To lead the army", "To guard the ark", "To collect taxes", "To warn the people of danger"]}, {"q": "What did God show Ezekiel in chapter 37?", "options": ["A burning mountain", "A valley of dry bones coming to life", "A golden idol", "A great flood"]}, {"q": "What does God promise in Ezekiel 36:26?", "options": ["A new heart and a new spirit", "A new city of stone", "A new king", "A new law of fines"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Visions of Glory: Ezekiel$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,1,0}'::int[], array[$j$Ezekiel was among the exiles by the river Chebar in the land of the Chaldeans.$j$,$j$The watchman blows the trumpet to warn the people.$j$,$j$The vision pictured God restoring Israel to life.$j$,$j$God promised to give a new heart and put a new spirit within His people.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Visions of Glory: Ezekiel$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Faith in the Fire: Daniel$j$, $j${"questions": [{"q": "Which three friends were thrown into the fiery furnace?", "options": ["Peter, James and John", "Shem, Ham and Japheth", "Gad, Asher and Dan", "Shadrach, Meshach and Abednego"]}, {"q": "Why was Daniel thrown into the den of lions?", "options": ["He prayed to God against the king's law", "He stole food", "He refused to wear a crown", "He fought a soldier"]}, {"q": "What did the king see in the furnace?", "options": ["Only the three friends", "A great wall", "No one", "Four men walking in the fire"]}, {"q": "What does Daniel 7:14 teach about God's kingdom?", "options": ["It is for one nation only", "It will end with Babylon", "It belongs only to Persia", "It is an everlasting dominion that will not be destroyed"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Faith in the Fire: Daniel$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,3}'::int[], array[$j$Shadrach, Meshach and Abednego refused to bow to the golden image.$j$,$j$Daniel kept praying to God even after the law was signed.$j$,$j$Nebuchadnezzar saw four men loose in the fire, and the fourth was like the Son of God.$j$,$j$The kingdom given to the Son of man is everlasting and shall not be destroyed.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Faith in the Fire: Daniel$j$ on conflict (item_id) do nothing;
